quests[43635] = { id = 43635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wohl der Vielen", description = "[DIES IST EINE VORÜBERGEHENDE QUEST, DAMIT IHR NACH DALARAN AUF DEN VERHEERTEN INSELN KOMMT.]\n\nBitte nehmt das Portal nach DALARAN auf den Verheerten Inseln und beginnt mit Eurer Artefaktquest!", sourceObjective = "Nehmt über Karazhan das Portal nach Dalaran auf den Verheerten Inseln.", sourceObjectiveStatus = "unverified-source-field" }
