quests[43641] = { id = 43641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Arkus: Wandernde Seuche" }
quests[43642] = { id = 43642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Der Kummer" }
quests[43643] = { id = 43643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Äxte", description = "Ich habe eine Bitte, <Schlachtenfürst/Schlachtenfürstin>. Ich brauche Inspiration! Eine Axt, deren Form eine wahrhaft erstaunliche Anzahl Kämpfe durchgemacht hat und die von einem der mächtigsten Krieger der Welt geführt wurde. Waffe und Besitzer, die im Schmelztiegel des Krieges zusammengeschweißt wurden.\n\nSucht einen solchen Helden samt Waffe und überzeugt ihn davon, herzukommen.", sourceObjective = "Durchsucht die Verheerten Inseln nach dem größten axtschwingenden Krieger, den Ihr kennt.", progress = "Habt Ihr ihn gefunden?", completion = "Vielen Dank, Schlachtenfürst. Die Valarjar werden wesentlich besser ausgerüstet sein, sobald ich alles angepasst habe.\n\nAuch Eure Waffe hat mich inspiriert. Klingenspalter. Das ist in meinen Augen der Name, den sie verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[43644] = { id = 43644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefen", description = "Ich versichere Euch, die Legenden sind wahr: Das Szepter der Gezeiten, Sharas'dal, wurde um lebendes Wasser des Brunnens der Ewigkeit herum geformt und hat Azshara die Herrschaft über das Leben selbst verliehen. Ich habe viele Schamanen auf der ganzen Welt danach suchen lassen, aber die einzige, die es gefunden hat, wird seitdem vermisst.\n\nDie Wellensprecherin Adelee sagte, sie hätte das Szepter in den Ruinen von Vashj'ir aufgespürt. Seitdem haben wir nichts mehr von ihr gehört.\n\n{name}! Reist mit mir in die Tiefen des Ozeans. Suchen wir die verschollene Schamanin und bergen wir dieses Artefakt!", sourceObjective = "Reist mit Erunak zu den Ruinen von Vashj'ir.", progress = "Ich kann uns in die Tiefen bringen. Betretet diese Blase hier... Sie ist relativ sicher.", completion = "Sehr gut!\n\nWenn Ihr noch nie in diesem Reich gewesen seid, dann kann ich Euch ein paar Tricks verraten, wie Ihr \"seetauglich\" werdet und für die Dauer der Mission hier unter Wasser atmen könnt.\n\nJetzt lasst uns die verschollene Schamanin und das Szepter suchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[43645] = { id = 43645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spur der Wellensprecherin", description = "Die Schamanin, die wir suchen, ist Wellensprecherin Adelee. Ihre Forschungen haben sie zu diesen uralten Ruinen geführt. Von ihr stammte der Bericht, dass sich hier vor der Legionsinvasion Armeen von Naga zusammengezogen haben.\n\nDas Letzte, was ich von ihr hörte, war, dass sie Sharas'dal, das Szepter der Gezeiten, gefunden hatte. Danach herrschte Schweigen.\n\n{name}, sucht nach Hinweisen für ihren Aufenthaltsort auf den unteren Ebenen der Ruinen. Achtet auf Nagapatrouillen!", sourceObjective = "Findet drei Hinweise auf den Aufenthaltsort von Wellensprecherin Adelee innerhalb der Ruinen von Vashj'ir.", progress = "Was macht die Suche?", completion = "<Ihr meldet Eure Funde Erunak, der geistesabwesend zuhört, während er das von Euch gefundene Tagebuch durchblättert.>\n\nDie Naga haben also Meeresriesen auf ihre Seite gezogen? Das ist besorgniserregend.\n\nAdelees Tagebuch bestätigt meine Befürchtungen. Die Naga sind wieder einmal in den Meeresschlund vorgedrungen, und dieses Mal führen sie eine mächtige Waffe mit sich: Sharas'dal. Es ist klar, was wir zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
