quests[43685] = { id = 43685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phylactery Used" }
quests[43686] = { id = 43686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vierte Reiter", description = "Der Lichkönig verlangt zu viel! Tirion Fordring verdient mehr als nur ein leidvolles und untotes Leben!\n\nHört zu, <Todesgebieter/Todesgebieterin>... Ich werde mich Eurem Willen beugen, aber für das, was wir tun werden, gibt es keine Wiedergutmachung.\n\nDie Silberne Hand wird uns Tirion niemals ausliefern. Der Weg der Vier Reiter wird mit dem Blut der Rechtschaffenen getränkt werden!\n\nDieses Blut wird uns auf ewig an den Händen kleben.\n\nEuer Wille soll geschehen, <Todesgebieter/Todesgebieterin>. Ich werde Vorbereitungen für die Invasion der Kapelle des Hoffnungsvollen Lichts treffen. Wenn es das braucht, um unsere Welt zu retten, dann soll es so sein!", sourceObjective = "Gewinnt den Vierten Reiter für Eure Sache.", completion = "Ich verstehe nun, was mir zuvor verborgen war. Mein Schicksal ist seit langer Zeit vorherbestimmt.\n\nDiese Last zu tragen, war schon immer mein Los.", sourceObjectiveStatus = "unverified-source-field" }
quests[43687] = { id = 43687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schatten wandeln", description = "Wenn wir die Macht des Splitters in den Aschenbringer einbringen wollen, brauchen wir Hilfe. Wir können mit solch dunkler Magie nicht umgehen, aber ich weiß, wer es kann...\n\nDie Ritter der Schwarzen Klinge.\n\nIch werde für Euch einen Flug nach Acherus arrangieren und mich dort mit Euch treffen. Sucht Aludane Wolkenweiß in Dalaran auf, wenn Ihr bereit seid.", sourceObjective = "Bittet die Ritter der Schwarzen Klinge in Acherus über den Verheerten Inseln um Hilfe.", completion = "Es ist vollbracht. Ich hoffe, Ihr behaltet recht, Hochlord.", sourceObjectiveStatus = "unverified-source-field" }
quests[43688] = { id = 43688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shard Delivered" }
quests[43689] = { id = 43689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulfiend Tagerma" }
quests[43690] = { id = 43690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shroudseeker" }
quests[43691] = { id = 43691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plaguemaw" }
quests[43693] = { id = 43693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion: Azshara" }
quests[43695] = { id = 43695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Pair of Goggles" }
quests[43696] = { id = 43696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Lumenstone 1" }
quests[43697] = { id = 43697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieger des Lichts", description = "Wir haben uns hier versammelt, um unseren heutigen Sieg über die Brennende Legion zu feiern. Gesellt Euch doch bitte zu uns, Hochlord.", sourceObjective = "Hört zu, während der Orden der Silbernen Hand Euch würdigt.", progress = "Auf unseren Triumph! Hurra!", completion = "Wir danken Euch, dass Ihr uns zum Sieg geführt habt. Hoch lebe Hochlord {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[43698] = { id = 43698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtstein", description = "Um uns auf die kommende Schlacht vorzubereiten, brauchen wir die Rüstungen und Waffen.\n\nWir haben von Leuchtstein gehört. Das ist ein verzaubertes Material, das Magie aufheben kann... sogar Teufelsmagie.\n\nMan findet kleine Vorkommen im ganzen Gebiet der Verheerten Inseln. Viele der einheimischen Völker verwenden es in der Metallverarbeitung.\n\nWir sollten unsere Champions ausschicken, um Ziele auf den Verheerten Inseln zu überfallen. Unter ihren Vorräten sollte sich jede Menge Leuchtstein finden lassen.", sourceObjective = "Sammelt 50 Stücke Leuchtstein, indem Ihr Champions auf Missionen der Reihe \"Leuchtstein\" schickt.", progress = "Habt Ihr schon Leuchtstein gefunden?", completion = "Das ist genug Leuchtstein, um Rüstungen und Waffen für eine ganze Armee herzustellen. Vielen Dank, Hochlord.", sourceObjectiveStatus = "unverified-source-field" }
quests[43699] = { id = 43699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger der Welt", description = "Aus den gesamten Verheerten Inseln erreichen uns Hilferufe nach Eurem Beistand, Hochlord.\n\nIch weiß, dass wir gerade die Priester im Netherlichttempel unterstützen, aber es gibt noch andere, die unsere Hilfe benötigen.\n\nWir dürfen niemanden im Stich lassen, der unseren Beistand braucht.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Vielen Dank, Hochlord. In diesen dunklen Zeiten gibt es einfach zu viele Gefahren. Aber solange Helden wie Ihr gegen das Böse kämpfen, wird unser Leben ein wenig sicherer.", sourceObjectiveStatus = "unverified-source-field" }
quests[43700] = { id = 43700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht in der Dunkelheit", description = "Hochlord, wie gut, dass Ihr hier seid! Die Invasion des Netherlichttempels hat begonnen.\n\nUnsere Streitkräfte warten schon auf der anderen Seite des Portals.\n\nStoßt zu ihnen, dann lassen wir die Falle um Lord Balnazzar zuschnappen.", sourceObjective = "Begebt Euch mithilfe des Portals des Priesters in Dalaran zum Netherlichttempel, verteidigt dann den Netherlichttempel und vernichtet Lord Balnazzar.", completion = "Der Sieg ist unser, Hochlord.", sourceObjectiveStatus = "unverified-source-field" }
quests[43701] = { id = 43701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lothraxion", sourceObjective = "Ich bin sicher, Ihr habt viele Fragen, Hochlord {name}. Das Schicksal hat uns an jenem Tag auf Niskara zusammengeführt.\n\nIch diene dem Hochexarchen Turalyon und Lady Alleria Windläufer. Als die Legion gegen Azeroth marschierte, wurde ich hierhergeschickt, um diese Welt zu beschützen.\n\nWie ich dann nach Niskara kam, ist eine andere Geschichte, die wir auf später verschieben müssen. Ohne Euch wäre ich aber wohl immer noch in den Fängen von Balnazzar.\n\nEndlich kann ich meine ursprüngliche Mission erfüllen. Lasst mich für Euch kämpfen. Gemeinsam werden wir die Brennende Legion in die Flucht schlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[43702] = { id = 43702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermürbung des Ziels", description = "Das Ende des Erzdruiden ist nahe. Aber seine Erinnerung wird in den Herzen aller weiterleben, die ihn kannten.\n\nElothirs verzweifelte Anstrengung hat gezeigt, dass Malfurion in Shala'nir festgehalten wird, zwischen den Wurzeln von Shaladrassil.\n\nMein Liebster. So nah und doch so fern...\n\nShala'nir ist von Alptraumkreaturen überrannt. Ein Frontalangriff wäre Selbstmord.\n\nIch habe eine von Xavius' Kreaturen unterjocht. Setzt sie gegen ihn ein, {name}, und bahnt uns einen Weg.", sourceObjective = "Tötet 50 Alptraumkreaturen in Shala'nir, während Ihr auf der unterjochten Nachtschwinge reitet.", progress = "Habt Ihr die Reihen des Feindes ausgedünnt?", completion = "Dieser Ort bleibt eine Todesfalle, aber nun können wir uns tiefer hineinwagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43703] = { id = 43703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hub Mana Tree Tracking - Stage 01" }
quests[43704] = { id = 43704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hub Mana Tree Tracking - Stage 02" }
quests[43705] = { id = 43705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nobundos letztes Gefecht", description = "Die Exodar erzitterte unter dem Ansturm der Legion. Bevor wir reagieren konnten, wimmelte es in den Hallen nur so von Dämonen. Sie brachten alle um, die sich ihnen in den Weg stellten. Ohne den Propheten wären wir wohl alle in diesem ersten Angriff gefallen.\n\nMeine Aufgabe war, die Kristallhalle zu evakuieren. So wurden meine Zerschlagenen und ich von der Hauptstreitmacht getrennt.\n\nWir zogen uns in die eingestürzte Halle zurück, um hier unser letztes Gefecht zu bestreiten.\n\nMit Eurer Hilfe könnten wir diese Invasion vielleicht doch noch überleben.", sourceObjective = "Verteidigt Scharfseher Nobundo gegen den Sturmangriff der Legion.", progress = "Die Legion muss fallen!", completion = "Ich danke Euch, tapferer Held. Alle Zerschlagenen danken Euch. Viele hätten uns wohl als akzeptablen Verlust abgeschrieben, aber Ihr habt großes Mitgefühl und wahre Güte bewiesen. Das werde ich... das wird keiner von uns je vergessen.\n\nWir kehren nun in die Halle des Lichts zurück und helfen Velen, so gut wir können.", sourceObjectiveStatus = "unverified-source-field" }
quests[43706] = { id = 43706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hub Mana Tree Tracking - Stage 03" }
