quests[43723] = { id = 43723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Taoshi", sourceObjective = "Ich fühle mich über alle Maßen geehrt, {name}. Ich werde Euch mit Freuden als Champion dienen.\n\nSagt mir einfach, wohin es gehen soll. Ich kann mich überall einschleichen und alles herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43724] = { id = 43724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Meister Mathias Shaw", sourceObjective = "Wollen wir eine Allianz eingehen, Ihr und ich? Natürlich würde ich es niemals wagen, offiziell Mitglied der Ungekrönten zu werden, vom Schattenrat ganz zu schweigen.\n\nMir untersteht schließlich SI:7.\n\nAber solltet Ihr je meinen Rat oder meine Hilfe brauchen, genügt schon ein Wort. Ich werde zur Stelle sein. Wir werden im Geheimen zusammenarbeiten und dafür sorgen, dass die Brennende Legion fällt.", sourceObjectiveStatus = "unverified-source-field" }
