quests[43748] = { id = 43748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Currency Treasure - Felsoul Hold" }
quests[43749] = { id = 43749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "<Mein Herr/Meine Dame>, ich würde mit der Nase in einem Buch stecken, ob die Tirisgarde mich unterstützt oder nicht... aber meine Möglichkeiten sind begrenzt. Mehr über Eure Waffe zu erfahren, wird sich als kritischer Vorteil im Kampf gegen die Legion erweisen. Davon bin ich überzeugt.\n\nWenn Ihr weitere Forscher für diese Arbeit braucht, damit Ihr schneller Ergebnisse erzielt, dann müssen wir die Mittel zur Verfügung stellen, damit sie arbeiten können.\n\nIch verspreche, es wird jede Minute wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ihr seid entzückend. Einfach nur entzückend. Ich mache mich sofort an die Arbeit.\n\nDenkt an uns, wenn die Tirisgarde irgendwelche Ressourcen entbehren kann. Wenn Ihr die Forscher weiterhin beschäftigt, sollten wir bald alles, was es über Eure Waffe zu wissen gibt, herausgefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[43750] = { id = 43750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Schlacht", description = "Einst handelten die mächtigen, von den Titanen geschaffenen Hüter von Ulduar und Odyn als Einheit. Seit Odyn alles hinter sich gelassen hat, um die Valarjar zu erschaffen, wird nicht einmal mehr Odyns Sohn Thorim auf den Rat seines Vaters hören.\n\nEs gibt allerdings eine Hoffnung, die Mächte der Himmelsfeste und Ulduar wiederzuvereinen.\n\nDas Gjallarhorn war ein Geschenk von Hymdall vor Odyns Weggang. Die Hüter von Ulduar sind durch einen Eid verpflichtet, dem Ruf des Gjallarhorns zu folgen, wenn er ertönt, da dies das Signal wäre, dass das Ende der Zeit angebrochen ist!", sourceObjective = "Sprecht mit Hymdall.", completion = "Ah ja, das Gjallarhorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[43751] = { id = 43751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klar Schiff machen" }
