quests[43784] = { id = 43784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was für ein Alptraum" }
quests[43785] = { id = 43785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Arator der Erlöser", sourceObjective = "Hochlord {name}, seit vielen Jahren habe ich versucht, in die Fußstapfen meines Vaters Turalyon zu treten.\n\nIn Euch erkenne ich einen beispielhaften Anführer, der mir immer noch viel beibringen kann. In Euch sehe ich einen Champion, der es mit meinem Vater aufnehmen könnte.\n\nIch würde mein Leben dafür geben, für den Orden der Silbernen Hand kämpfen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
