quests[43797] = { id = 43797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für die Konklave", description = "Die Priester der Konklave sind mächtige Verbündete. Gemeinsam haben wir vielleicht sogar eine Chance, den Schreckenslord für immer zu vernichten.\n\nLasst Alonsus Faol wissen, dass wir Euch zur Seite stehen und mit Euch kämpfen werden, wann immer Ihr uns braucht.", sourceObjective = "Kehrt zu Alonsus Faol im Netherlichttempel zurück.", completion = "Mit den Paladinen an unserer Seite als Verbündete im Lichte ist die Prophezeiung nun erfüllt.\n\nWir müssen uns vorbereiten. Balnazzar wird bald angreifen.", sourceObjectiveStatus = "unverified-source-field" }
