quests[43805] = { id = 43805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meucheln unter Wasser" }
quests[43806] = { id = 43806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Verheerte Küste", description = "Die dritte Flotte ist bereits vor uns ausgelaufen, {name}. Dieser Greif wird Euch dorthin bringen.\n\nViel Glück da draußen. Die Legion wird es uns bestimmt nicht leicht machen. Hoffen wir nur, dass König Varian die Lage im Griff hat.", sourceObjective = "Trefft Euch mit der dritten Flotte.", completion = "Ah, {name}, Ihr seid auf den Beinen! Ich bin erleichtert, dass Ihr dieses Blutbad überlebt habt. Wir haben dort unten so viele gute Männer und Frauen verloren...\n\n\n\nVerdammt soll die Horde sein, dass sie uns der Legion wie auf einem Silbertablett serviert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[43807] = { id = 43807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdorrte Streitereien: Zinnobertal" }
quests[43808] = { id = 43808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondwachenteleporter bereit!", description = "<Der telemantische Signalgeber ist deaktiviert, aber intakt. Mit etwas uraltem Mana sollte er bald wieder einsatzbereit sein.>", sourceObjective = "Reichert den telemantischen Signalgeber mit uraltem Mana an.", progress = "<Der Signalgeber ist kalt und dunkel.>", completion = "<Der Signalgeber beginnt zu leuchten, als Ihr ihn mit uraltem Mana anreichert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43809] = { id = 43809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tel'anor'eporter bereit!", description = "<Der telemantische Signalgeber ist deaktiviert, aber intakt. Mit etwas uraltem Mana sollte er bald wieder einsatzbereit sein.>", sourceObjective = "Reichert den telemantischen Signalgeber mit uraltem Mana an.", progress = "<Der Signalgeber ist kalt und dunkel.>", completion = "<Der Signalgeber beginnt zu leuchten, als Ihr ihn mit uraltem Mana anreichert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43810] = { id = 43810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Arbeit", description = "Alles der Reihe nach, {name}: Wir müssen ein Lager aufschlagen.\n\nWir verfügen nicht über genug Zeit und Ressourcen für eine lange Belagerung. Wir können sie nicht aushungern. Nein, wir müssen schnell wie der Pfeil eines Bogens sein und sie direkt ins Herz treffen.\n\nSie beziehen Stellung in der Stadt, aber sie könnten uns angreifen, während wir unsere Verteidigung aufstellen.\n\nGeht voraus und zeigt ihnen, was die Kaldorei in tausenden Jahren Krieg gelernt haben. Findet ihre Schwächen heraus, damit wir sie ausnutzen können.", sourceObjective = "Betretet die Große Promenade und tötet 15 Verteidiger.", completion = "Alles Bedauern, das ich für diese Leute empfand, war dahin, als sie unter dem Schild verschwanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43811] = { id = 43811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teleporter des Anwesens der Lunastres bereit!", description = "<Der telemantische Signalgeber ist deaktiviert, aber intakt. Mit etwas uraltem Mana sollte er bald wieder einsatzbereit sein.>", sourceObjective = "Reichert den telemantischen Signalgeber mit uraltem Mana an.", progress = "<Der Signalgeber ist kalt und dunkel.>", completion = "<Der Signalgeber beginnt zu leuchten, als Ihr ihn mit uraltem Mana anreichert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43812] = { id = 43812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Arbeit", description = "An die Arbeit, {name}. Wir dürfen keine Zeit verschwenden.\n\nWir werden uns hier zwar nicht lange niederlassen, aber wir brauchen dennoch eine Art Kriegslager. Ich glaube nicht, dass die Nachtgeborenen in der Stadt ruhig abwarten, während wir hier Pfähle in den Boden rammen.\n\nSie beginnen mit dem Aufbau ihrer eigenen Verteidigung. Begebt Euch da rein, um sie auszukundschaften. Ihr werdet sie auf eigenem Boden angreifen, während wir hier unsere Vorbereitungen abschließen.", sourceObjective = "Betretet die Große Promenade und tötet 15 Verteidiger.", completion = "Ausgezeichnet. So können wir erst einmal unsere Grenzen verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43813] = { id = 43813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teleporter des Sanktums der Ordnung bereit!", description = "<Der telemantische Signalgeber ist deaktiviert, aber intakt. Mit etwas uraltem Mana sollte er bald wieder einsatzbereit sein.>", sourceObjective = "Reichert den telemantischen Signalgeber mit uraltem Mana an.", progress = "<Der Signalgeber ist kalt und dunkel.>", completion = "<Der Signalgeber beginnt zu leuchten, als Ihr ihn mit uraltem Mana anreichert.>", sourceObjectiveStatus = "unverified-source-field" }
