quests[43828] = { id = 43828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sheep Summon Daily Roll" }
quests[43829] = { id = 43829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spion gegen Spion", description = "Der SI:7 ist in der Allianz für Spionage und Informationsbeschaffung zuständig. Die Operationsbasis der Organisation liegt in Sturmwind und angeführt werden sie von Meister Mathias Shaw. Aber seit einiger Zeit verhalten sie sich merkwürdig... gelinde gesagt.\n\nIhr solltet einige unserer Leute ausschicken, um die Situation genauer zu untersuchen. Vielleicht ist ja nichts dabei, aber ich mag es einfach nicht, wenn mir etwas merkwürdig vorkommt.\n\nDer Krieg gegen die Brennende Legion erfordert unsere volle Konzentration. Unvorhergesehene Probleme können wir uns nicht leisten.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Spion und Spion\" ab.", completion = "Warum erhöht Mathias Shaw die Anzahl seiner Agenten im Gebiet der Horde?\n\nWir müssen diese Situation genau im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43830] = { id = 43830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 001 - South of Felsoul" }
quests[43831] = { id = 43831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 002 - Felsoul Upper" }
quests[43832] = { id = 43832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfreiche Elixiere", description = "Man kann niemals gut genug für eine Schlacht gewappnet sein. Die Legion wird jeden Moment angreifen, und wir müssen uns auf viele Verwundete und Kranke vorbereiten.\n\nZabra und Yalia haben mir eine Liste ihrer stärksten Tränke und Kampfelixiere gegeben. Damit ist so gut wie alles möglich, von der Wiederherstellung der eigenen Gesundheit bis zum Blenden eines Gegners.\n\nDie Liste der Zutaten, die wir für einen ausreichenden Vorrat benötigen, ist entsprechend lang.", sourceObjective = "Sammelt Elixierzutaten für Alonsus Faol.", completion = "Ihr seid ebenso zuverlässig wie vielseitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[43833] = { id = 43833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 003 - Felsoul Lower" }
