quests[43840] = { id = 43840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 008 - Collapse Depths" }
quests[43841] = { id = 43841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Alte Yancey muss mit", description = "Aufgepasst! Es wird Zeit, dass wir etwas frisches Piratenblut an Deck bekommen.\n\n<Knacker krächzt lauthals seine Zustimmung.>\n\nUnd ich weiß, wer dabei am Ruder stehen muss.\n\nIch meine natürlich den guten alten Yancey Grillsen. Der alte Seebär steckt irgendwo im Schlingendorntal.\n\nSchickt doch ein paar Eurer Landratten los, die ihn einsacken.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Der Alte Yancey muss mit\" ab.", completion = "Harrr! Das wollte ich hören.\n\nUnd, Knacker, können wir mit ein paar Freibeutern wieder klar Schiff machen oder laufen wir voll auf Grund? Tja, das weiß wohl nur der Klabautermann.", sourceObjectiveStatus = "unverified-source-field" }
quests[43842] = { id = 43842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 009 - Ambervale Ruins" }
