quests[43850] = { id = 43850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 017 - Telanor Harpy" }
quests[43851] = { id = 43851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung weiterer Truppen", description = "Die Kunde, dass Ihr den Oberbefehl übernommen habt, verbreitet sich wie ein Lauffeuer. Alle möglichen Priester sind zum Tempel gekommen, um ihre Hilfe anzubieten.\n\nZu unserem Glück ist auch Vikarin Eliza auf uns aufmerksam geworden. Sie ist selbst eine charismatische Anführerin, und zahllose Gläubige gehorchen jedem ihrer Befehle.\n\nSprecht jetzt mit ihr.", sourceObjective = "Sprecht mit Vikarin Eliza.", completion = "Es ist mir eine Ehre, Euch zu dienen, Hohepriester.", sourceObjectiveStatus = "unverified-source-field" }
quests[43852] = { id = 43852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feine Pinkel und Bukaniere", description = "Aye, mir wird ganz warm ums Herz, dass Yancey jetzt mit an Bord ist.\n\n<Tethys füttert Knacker mit ein paar Eiern vom Tisch.>\n\nSeid doch bitte ein <lieber Junge/liebes Mädchen> und schaut mal, ob Ihr nicht ein paar Bilgeratten auftreiben könnt.", sourceObjective = "Sprecht mit Eurem Piratenrekrutierer Yancey Grillsen.", completion = "Das ist schon besser. Gebt Ihnen etwas Bimsstein und lasst sie das Deck schrubben.\n\nZusammen mit ein paar Krügen Rum wird ihnen das schon auf die Seebeine helfen. Ha!", sourceObjectiveStatus = "unverified-source-field" }
