quests[43877] = { id = 43877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Jeder Todesritter, der etwas auf sich hält, kennt die Waffen, die er führt, als ob er mit ihnen geboren worden wäre. Doch Ihr tragt jetzt eine Waffe, die älter ist als jede andere hier in dieser Halle.\n\nWenn wir wirklich ihre ganze Kraft freisetzen wollen, dann müssen wir mehr darüber lernen. Es wird Zeit und mehr Augen als nur meine brauchen, um diese gesamte Geschichte zu sichten, zu übersetzen und in etwas Verständliches zu verwandeln.\n\nWir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ausgezeichnet. Ich melde mich mit den Ergebnissen bei Euch, sobald ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[43878] = { id = 43878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Ein Dämonenjäger ist nichts ohne Klingen, mit denen er in Fleisch schneiden kann. Doch die Klingen, die Ihr dort führt, sind älter als Ihr... und besitzen eine Macht, die wir selbst noch nicht verstehen.\n\nWenn wir wirklich ihre ganze Kraft freisetzen wollen, dann müssen wir mehr darüber lernen. Es wird Zeit und mehr Augen als nur meine brauchen, um diese gesamte Geschichte zu sichten, zu übersetzen und in etwas Verständliches zu verwandeln.\n\nWir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ausgezeichnet. Ich melde mich mit den Ergebnissen bei Euch, sobald ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[43879] = { id = 43879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Ihr seid im Besitz einer uralten und mächtigen Waffe, und doch verstehen wir kaum etwas von ihr. Wenn wir wirklich ihr gesamtes Potenzial freisetzen wollen, müssen wir mehr darüber erfahren. Und genau hier komme ich ins Spiel. Das ist meine Spezialität.\n\nAber dennoch – es wird Zeit und mehr Augen als nur meine brauchen, um diese gesamte Geschichte zu sichten, zu übersetzen und in etwas Verständliches zu verwandeln.\n\nWir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ausgezeichnet. Ich melde mich mit den Ergebnissen bei Euch, sobald ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[43880] = { id = 43880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Ihr seid im Besitz einer uralten und mächtigen Waffe, und doch verstehen wir kaum etwas von ihr. Wenn wir wirklich ihr gesamtes Potenzial freisetzen wollen, müssen wir mehr darüber erfahren. Ich kann Euch dabei helfen.\n\nIch werde aber Zeit und ein paar zusätzliche Augen brauchen, um diese gesamte Geschichte zu durchforsten, zu übersetzen und in etwas Verständliches zu verwandeln.\n\nWir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ausgezeichnet. Ich melde mich mit den Ergebnissen bei Euch, sobald ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[43881] = { id = 43881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Ihr seid im Besitz einer uralten und mächtigen Waffe, und doch verstehen wir kaum etwas von ihr. Wenn wir wirklich ihr gesamtes Potenzial freisetzen wollen, müssen wir mehr darüber erfahren. Ich habe ein gewisses Talent auf diesem Gebiet.\n\nAber es wird Zeit und mehr Augen als nur meine brauchen, um diese gesamte Geschichte zu sichten, zu übersetzen und in etwas Verständliches zu verwandeln.\n\nWir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ausgezeichnet. Ich melde mich mit den Ergebnissen bei Euch, sobald ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[43882] = { id = 43882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Gewölbe", description = "Die Nachtfestung zu infiltrieren und einzunehmen, wird eine echte Herausforderung. Selbst ihre Katakomben und Gewölbe sind vermutlich streng bewacht, aber wir müssen auf jeden Fall einen Weg hinein finden.", sourceObjective = "Tötet Trilliax in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43883] = { id = 43883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Ihr seid im Besitz einer mächtigen Waffe mit einer langen Geschichte, von der wir kaum etwas verstehen. Wenn wir wirklich ihr gesamtes Potenzial freisetzen wollen, müssen wir mehr darüber erfahren. Ich könnte mich für Euch darum kümmern.\n\nAber es wird Zeit und mehr Augen als nur meine brauchen, um diese gesamte Geschichte zu sichten, zu übersetzen und in etwas Verständliches zu verwandeln.\n\nWir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ausgezeichnet. Ich melde mich mit den Ergebnissen bei Euch, sobald ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[43884] = { id = 43884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Ihr seid im Besitz einer uralten und mächtigen Waffe, und doch verstehen wir sie kaum. Wenn wir wirklich ihr gesamtes Potenzial freisetzen wollen, müssen wir mehr darüber erfahren. Ich könnte das für Euch erledigen.\n\nAber es wird Zeit und mehr Augen als nur meine brauchen, um diese gesamte Geschichte zu sichten, zu übersetzen und in etwas Verständliches zu verwandeln.\n\nWir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ausgezeichnet. Ich melde mich mit den Ergebnissen bei Euch, sobald ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[43885] = { id = 43885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Eure Waffen sind unbestreitbar mächtig, aber wir wissen fast nichts über sie.\n\nWenn wir ihr gesamtes Potenzial freisetzen wollen, müssen wir ein wenig wühlen und rausfinden, wie sie funktionieren, was sie gemacht haben... sie kennenlernen, wisst Ihr? Da komm ich ins Spiel. Ich wühle nur zu gern im Dreck. Also, nicht wortwörtlich, aber... Ihr wisst schon, was ich meine.\n\nAber es wird Zeit und mehr Augen als nur meine brauchen, um diese gesamte Geschichte zu sichten. Wir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Bin dran, Boss. Melde mich bald wieder!", sourceObjectiveStatus = "unverified-source-field" }
quests[43886] = { id = 43886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Wind sprechen", description = "Ihr seid im Besitz einer uralten und mächtigen Waffe. Wir kennen Geschichten über sie, aber wir wissen nur wenig über ihre Herkunft.\n\nWenn wir wirklich ihr gesamtes Potenzial freisetzen wollen, müssen wir mehr darüber erfahren. Die Winde können uns dabei helfen, aber nur, wenn wir wissen, welche Fragen wir stellen müssen.\n\nWir benötigen mehr Schamanen als nur mich, wenn wir alles über Euer Artefakt herausfinden wollen. Wir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Danke. Ich werde Euch bald mitteilen, was ich erfahren konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[43887] = { id = 43887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Ihr seid im Besitz einer uralten und mächtigen Waffe, und doch verstehen wir kaum etwas von ihr. Wenn wir wirklich ihr gesamtes Potenzial freisetzen wollen, müssen wir mehr darüber erfahren. Diese Aufgabe übernehme ich gern für Euch.\n\nAber es wird Zeit und mehr Augen als nur meine brauchen, um diese gesamte Geschichte zu sichten, zu übersetzen und in etwas Verständliches zu verwandeln.\n\nWir sollten einige Ressourcen des Ordens für diese Aufgabe abstellen. Ich verspreche Euch, das Ergebnis wird den Aufwand wert sein.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Sehr gut. Ich melde mich bald mit den Ergebnissen bei Euch.", sourceObjectiveStatus = "unverified-source-field" }
